import heapq


def _ledger(priority, tax_base):
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", f"anonymous:{position}")
            if priority == "sequence_first":
                key = (sequence, event.get("revision", 0), position)
            else:
                key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        half_up = data["rounding"] == "half_up"

        def rounded(numerator):
            return ((numerator + 5000) // 10000 if half_up
                    else numerator // 10000)

        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = raw if tax_base == "original" else net
            tax = rounded(base * event.get("tax_bp", 0))
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {row["version"]: row for row in package_rows}
            for name, package_rows in packages.items()}
    version_choices = [list(rows[name]) for name in names]
    best_key = None
    best = None

    for versions in product(*version_choices):
        assigned = dict(zip(names, versions))
        constraints = {name: [bounds] for name, bounds in data["roots"].items()}
        graph = {}
        installed = set()
        pending = list(data["roots"])
        valid = True

        while pending and valid:
            name = pending.pop()
            if name in installed:
                continue
            installed.add(name)
            version = assigned[name]
            if (version in blocked.get(name, []) or
                    (name in pins and pins[name] != version) or
                    any(not low <= version <= high
                        for low, high in constraints.get(name, []))):
                valid = False
                break

            active_deps = []
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                active_deps.append(dep)
                constraints.setdefault(dep["name"], []).append(
                    (dep["min"], dep["max"]))
                pending.append(dep["name"])
            graph[name] = [dep["name"] for dep in active_deps]

        if not valid:
            continue
        if any(any(not low <= assigned[name] <= high
                   for low, high in constraints.get(name, []))
               for name in installed):
            continue

        state = {}
        def acyclic(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not acyclic(other) for other in graph.get(name, [])):
                return False
            state[name] = 2
            return True

        if any(not acyclic(name) for name in installed):
            continue

        result = {name: assigned[name] for name in installed}
        key = tuple(result.get(name, -1) for name in names)
        if best_key is None or key < best_key:
            best_key, best = key, result

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _quota_intervals(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in set(data.get("blocked", []))]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue

        value = sum(job["value"] for job in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required_bits = {node: 1 << index
                     for index, node in enumerate(data.get("required", []))}
    full_mask = (1 << len(required_bits)) - 1
    source = data["source"]
    initial_mask = required_bits.get(source, 0)
    start_state = (source, initial_mask, 0)
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, used = heapq.heappop(queue)
        if distances.get((node, mask, used)) != time:
            continue
        if (node == data["target"] and mask == full_mask and
                used == data["coupons"]):
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | required_bits.get(next_node, 0)
                state = (next_node, next_mask, next_used)
                if arrival < distances.get(state, float("inf")):
                    distances[state] = arrival
                    heapq.heappush(queue, (arrival, next_node,
                                           next_mask, next_used))

    return {"arrival": None}


